pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.deposit{value: 1 ether}();

        vm.prank(alice);
        c.withdrawAll();

        // Reference: after withdrawal, contract balance should be 0.
        // Bug: after withdrawal, contract balance becomes 2 ether (mis-added instead of subtracted).
        assertTrue(address(c).balance < 1 ether);
    }
}

